document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.page){page=b.dataset.page;filter='';search='';ipTab='';credTab='';run(load)}if(b.dataset.iptab!==undefined){ipTab=b.dataset.iptab;render()}if(b.dataset.credtab!==undefined){credTab=b.dataset.credtab;render()}if(b.dataset.folderRename){const from=credTab;modal('Rename folder',`<label class="field-wide">New name for “${E(from)}”<input name="to" value="${E(from)}" maxlength="80" list="folderlist" placeholder="Empty = remove folder"><datalist id="folderlist">${folders().filter(f=>f!==from).map(o=>`<option value="${E(o)}"></option>`).join('')}</datalist></label><p class="formnote field-wide">All entries in this folder are moved. Use an existing name to merge two folders, leave it empty to remove the folder.</p>`,async d=>{const r=await api('folder_rename',{from,to:d.to||''});credTab=(d.to||'').trim().replace(/\s+/g,' ');toast(r.changed+' '+(r.changed===1?'entry':'entries')+' moved')})}if(b.dataset.ping)run(()=>pingDevice(Number(b.dataset.ping)));if(b.dataset.pingAll)run(pingAll);if(b.dataset.account)run(()=>acct('password'));if(b.dataset.acct)run(()=>acct(b.dataset.acct));if(b.dataset.addRow){const box=b.closest('.listfield'),list=box.querySelector('.listrows');list.insertAdjacentHTML('beforeend',listRow(b.dataset.addRow,'',box.dataset.ph||''));list.lastElementChild.querySelector('input').focus()}if(b.dataset.removeRow){const row=b.closest('.listrow');if(row.parentElement.children.length>1)row.remove();else row.querySelector('input').value=''}if(b.dataset.new)edit(b.dataset.new);if(b.dataset.edit){const r=get(b.dataset.edit);edit(r.kind,r.id)}if(b.dataset.delete)run(async()=>{const r=get(b.dataset.delete);if(confirm(r.kind==='racks'?'Permanently delete rack “'+r.data.name+'” and its '+records.filter(m=>m.kind==='mounts'&&m.data.rack===String(r.id)).length+' mounted items?':'Permanently delete “'+r.data.name+'”?')){closeModal();await api('delete',{id:r.id,revision:r.revision});await load()}});if(b.dataset.reveal)run(async()=>{const r=get(b.dataset.reveal),d=await api('reveal',{id:r.id});modal('Password · '+r.data.name,`<div class="secret">${E(d.password)}</div><p class="formnote">This window closes after 30 seconds. Access has been logged.</p>`,async()=>{});setTimeout(()=>{if($('#mtitle').textContent==='Password · '+r.data.name)closeModal()},30000)});if(b.dataset.copyPassword)run(async()=>{const d=await api('reveal',{id:Number(b.dataset.copyPassword)});if(!d.password)return toast('No password stored for this entry.');if(!navigator.clipboard||!window.isSecureContext)throw Error('Clipboard requires HTTPS. Use the eye icon to show the password.');await navigator.clipboard.writeText(d.password);toast('Password copied');});if(b.dataset.peek)run(()=>showLogin(Number(b.dataset.peek)));if(b.dataset.copyLink)run(async()=>{const c=get(b.dataset.copyLink),u=c&&safeUrl(c.data.url);if(!u)return toast('No link stored.');if(!navigator.clipboard||!window.isSecureContext)throw Error('Clipboard requires HTTPS.');await navigator.clipboard.writeText(u);toast('Link copied')});if(b.dataset.copyUser)run(async()=>{const c=get(b.dataset.copyUser);if(!c?.data.username)return toast('No username stored.');if(!navigator.clipboard||!window.isSecureContext)throw Error('Clipboard requires HTTPS.');await navigator.clipboard.writeText(c.data.username);toast('Username copied')});if(b.dataset.files)run(()=>showFiles(Number(b.dataset.files)));if(b.dataset.swUpload)softwareUpload();if(b.dataset.swEdit)softwareEdit(Number(b.dataset.swEdit));if(b.dataset.swDelete)run(async()=>{const f=software.files.find(x=>Number(x.id)===Number(b.dataset.swDelete));if(f&&confirm('Permanently delete “'+f.name+'” ('+f.filename+')?')){await api('software_delete',{id:Number(f.id)});toast('Deleted');await load()}});if(b.dataset.swCopy)run(async()=>{const f=software.files.find(x=>Number(x.id)===Number(b.dataset.swCopy));if(!navigator.clipboard||!window.isSecureContext)throw Error('Clipboard requires HTTPS.');await navigator.clipboard.writeText(f.sha256);toast('SHA-256 copied')});if(b.dataset.csv)run(()=>exportCsv(b.dataset.csv));if(b.dataset.newUser)modal('Add user','<label class="field-wide">Name<input name="display_name" maxlength="80" placeholder="e.g. Marco Muster" autocomplete="off"></label><label>Username<input name="username" pattern="[A-Za-z0-9._@-]{3,80}" required autocomplete="off"></label><label>Role<select name="role"><option value="reader">Read</option><option value="editor">Edit</option><option value="admin">Administrator</option></select></label><label>Temporary password<input name="password" type="password" minlength="14" maxlength="72" required autocomplete="new-password"></label><p class="formnote">Share the temporary password securely. The first sign-in requires a password change and 2FA setup.</p>',async data=>{await api('user_create',data);toast('User created');return ()=>acct('users')})});$('#close').onclick=$('#cancel').onclick=closeModal;$('#modal').addEventListener('cancel',()=>{fileViewGeneration++;if(uploadXhr)uploadXhr.abort();$('#fields').innerHTML=''});$('#logout').onclick=()=>run(async()=>{await api('logout',{});records=[];await init()});setInterval(()=>{if(user)run(async()=>{const s=await api('state');if(!s.user){records=[];closeModal();await init();toast('Session ended. Please sign in again.')}})},60000);run(init);
async function showFiles(credentialId){
    const request=++fileViewGeneration;
    const result=await api('attachments',{credential_id:credentialId});
    if(request!==fileViewGeneration||!user)return;
    const r=get(credentialId);if(!r)return;
    const canWrite=user.role!=='reader';
    modal('Files · '+r.data.name,`<p class="formnote field-wide">Encrypted attachments for this credential. Up to 5 MiB per file, 50 MiB per credential. Config files, SSH keys and encrypted connection files are downloaded as files and are never executed here.</p><div class="attachment-list field-wide">${result.files.length?result.files.map(f=>`<div class="attachment-row"><div><b>${E(f.filename)}</b><small>${(f.size/1024).toFixed(1)} KiB · ${E(f.created_at)}</small></div><div class="actions"><button type="button" data-download-file="${f.id}">Download</button>${canWrite?`<button type="button" data-remove-file="${f.id}">Delete</button>`:''}</div></div>`).join(''):'<p>No files attached yet.</p>'}</div>${canWrite?'<label class="field-wide">Add file<input id="attachment-file" type="file"><small>File contents are encrypted at rest. Names and file sizes remain visible to team members.</small></label><button class="primary field-wide" type="button" id="upload-file">Upload file</button>':''}`,async()=>{});
    $('#form').querySelector('.dialogactions button.primary').hidden=true;
    const panel=$('#fields');
    panel.querySelectorAll('[data-download-file]').forEach(b=>b.onclick=()=>run(async()=>{
        b.disabled=true;try{const f=await api('attachment_download',{id:Number(b.dataset.downloadFile)});const raw=atob(f.base64);const bytes=Uint8Array.from(raw,c=>c.charCodeAt(0));const href=URL.createObjectURL(new Blob([bytes],{type:'application/octet-stream'}));const a=document.createElement('a');a.href=href;a.download=f.filename;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(href),1000);toast('File downloaded');}finally{b.disabled=false;}
    }));
    panel.querySelectorAll('[data-remove-file]').forEach(b=>b.onclick=()=>run(async()=>{
        if(!confirm('Permanently delete this attachment?'))return;b.disabled=true;
        try{await api('attachment_delete',{id:Number(b.dataset.removeFile)});closeModal();await showFiles(credentialId);}finally{b.disabled=false;}
    }));
    if(canWrite)$('#upload-file').onclick=()=>run(async()=>{
        const f=$('#attachment-file').files[0];if(!f)throw Error('Choose a file first.');if(f.size>5242880)throw Error('Maximum file size is 5 MiB.');
        const button=$('#upload-file');button.disabled=true;
        try{const bytes=new Uint8Array(await f.arrayBuffer());let binary='';for(let i=0;i<bytes.length;i+=32768)binary+=String.fromCharCode(...bytes.subarray(i,i+32768));await api('attachment_upload',{credential_id:credentialId,filename:f.name,base64:btoa(binary)});closeModal();await showFiles(credentialId);toast('File uploaded');}finally{button.disabled=false;}
    });
}

function deviceLinks(id){const ls=records.filter(l=>l.kind==='links'&&(l.data.from===String(id)||l.data.to===String(id)));if(!ls.length)return '';return cardSec(id,'links','CONNECTIONS',`<span class="secnum">${ls.length}</span>${E(ls.slice(0,2).map(l=>l.data.name).join(' · '))}${ls.length>2?' …':''}`,`<div class="external-ips">${ls.map(l=>{const o=get(l.data.from===String(id)?l.data.to:l.data.from);return `<div class="linkrow"><span>${E(l.data.name)}</span>${E(o?.data.name||'—')}</div>`}).join('')}</div>`)}
let openSecs=new Set();function cardSec(id,key,label,info,body){const k=id+':'+key;return `<details class="cardsec" data-sec="${E(k)}" ${openSecs.has(k)?'open':''}><summary><span class="seclabel">${label}</span><span class="secinfo">${info}</span></summary><div class="secbody">${body}</div></details>`}
if(typeof document.addEventListener==='function')document.addEventListener('toggle',e=>{const d=e.target;if(d&&d.dataset&&d.dataset.sec){if(d.open)openSecs.add(d.dataset.sec);else openSecs.delete(d.dataset.sec)}},true);
const NW=220,NH=78;let mapPos={};
function mapNodes(){let di=0,ei=0;return records.filter(r=>r.kind==='elements'||r.kind==='devices').map(r=>{let x,y;if(r.data.x!==undefined&&r.data.x!==''){x=Number(r.data.x);y=Number(r.data.y)}else if(r.kind==='elements'){x=40;y=40+ei++*110}else{x=400+(di%2)*290;y=40+Math.floor(di++/2)*130}return {r,x,y}})}
function nodeStatus(r){const p=pings[r.id];if(r.kind!=='devices'||!p)return '';const up=p.results.filter(x=>x.up).length;return `<span class="dot ${up===p.results.length?'up':up?'partial':'down'}"></span>`}
function renderMap(){const can=user.role!=='reader',nodes=mapNodes();mapPos=Object.fromEntries(nodes.map(n=>[n.r.id,{x:n.x,y:n.y}]));const groups=pairGroups();
let h=`<div class="eyebrow">CIEGOLINK / CONNECTIONS</div><div class="heading"><div><h1>Connection <em>map.</em></h1><p>${can?'Drag boxes to arrange them. Drag from the round handle onto another box to connect them. Click a label to rename or delete a connection.':'See what is connected to what.'}</p></div>${can?'<div class="headactions"><button data-new="links">＋ Connection</button><button class="primary" data-new="elements">＋ Element</button></div>':''}</div>`;
h+=nodes.length?`<div class="mapwrap"><div class="mapcanvas" id="mapcanvas"><svg id="mapsvg" xmlns="http://www.w3.org/2000/svg">${Object.keys(groups).map(k=>`<path class="mapline" data-pair="${k}"></path>`).join('')}<line class="mapline temp" id="templine" visibility="hidden"></line></svg>${Object.entries(groups).map(([k,ls])=>`<div class="linkgroup" data-group="${k}">${ls.map(l=>can?`<button type="button" class="linklabel" data-edit="${l.id}" data-label="${l.id}" title="Edit connection">${E(l.data.name)}</button>`:`<span class="linklabel" data-label="${l.id}">${E(l.data.name)}</span>`).join('')}</div>`).join('')}${nodes.map(({r})=>{const d=r.data,u=safeUrl(d.url||d.webmin),sub=r.kind==='elements'?(u?new URL(u).host+(new URL(u).pathname.length>1?new URL(u).pathname:''):d.note||''):(ipSort(d.internal_ips).split('\n')[0]||ipSort(d.ip).split('\n')[0]||label(d.building));return `<div class="mapnode ${r.kind}" data-node="${r.id}"><span class="mapkind">${nodeStatus(r)}${E(d.type||(r.kind==='elements'?'Element':'Device'))}</span><b title="${E(d.name)}">${E(d.name)}</b><small>${E(sub)}</small>${u?`<a href="${E(u)}" target="_blank" rel="noopener noreferrer" title="Open">↗</a>`:''}${can?`<span class="handle" data-handle="${r.id}" title="Drag to connect"></span>`:''}</div>`}).join('')}</div></div>`:'<div class="empty">No devices or elements yet. Add an element such as “Website www.aw.plus”, then connect it to a device.</div>';
h+=foot();$('#main').innerHTML=h;if(nodes.length){layoutMap();if(can)bindMap()}}
// one line per pair of boxes, labels stacked
function pairGroups(){const g={};for(const l of records.filter(r=>r.kind==='links'&&mapPos[r.data.from]&&mapPos[r.data.to]&&r.data.from!==r.data.to).sort((x,y)=>x.id-y.id)){const k=[Number(l.data.from),Number(l.data.to)].sort((x,y)=>x-y).join('-');(g[k]=g[k]||[]).push(l)}return g}
function roundPath(p,r){let d=`M${p[0].x} ${p[0].y}`;for(let i=1;i<p.length-1;i++){const a=p[i-1],b=p[i],c=p[i+1],l1=Math.hypot(b.x-a.x,b.y-a.y),l2=Math.hypot(c.x-b.x,c.y-b.y),rr=Math.min(r,l1/2,l2/2);if(rr<1){d+=` L${b.x} ${b.y}`;continue}d+=` L${b.x+(a.x-b.x)/l1*rr} ${b.y+(a.y-b.y)/l1*rr} Q${b.x} ${b.y} ${b.x+(c.x-b.x)/l2*rr} ${b.y+(c.y-b.y)/l2*rr}`}const e=p[p.length-1];return d+` L${e.x} ${e.y}`}
function layoutMap(){const c=$('#mapcanvas');if(!c)return;let W=900,H=500;for(const [id,p] of Object.entries(mapPos)){const n=c.querySelector(`[data-node="${id}"]`);if(n){n.style.left=p.x+'px';n.style.top=p.y+'px'}W=Math.max(W,p.x+NW+120);H=Math.max(H,p.y+NH+120)}
const groups=pairGroups(),route={},sides={},anchor={},GAP=24;
for(const k of Object.keys(groups)){const [p,q]=k.split('-'),a=mapPos[p],b=mapPos[q],hg=Math.max(b.x-(a.x+NW),a.x-(b.x+NW)),vg=Math.max(b.y-(a.y+NH),a.y-(b.y+NH));let o,sa,sb;
if(hg>=GAP&&(hg>=vg||vg<GAP)){o='h';sa=b.x>a.x?'r':'l';sb=sa==='r'?'l':'r'}else if(vg>=GAP){o='v';sa=b.y>a.y?'b':'t';sb=sa==='b'?'t':'b'}else{o='o';sa=sb='r'}
route[k]={p,q,o};for(const [id,sd,other] of [[p,sa,q],[q,sb,p]])(sides[id+'|'+sd]=sides[id+'|'+sd]||[]).push({k,other})}
// spread lines on the same box side
for(const [key,list] of Object.entries(sides)){const [id,sd]=key.split('|'),n=mapPos[id],vert=sd==='l'||sd==='r';list.sort((x,y)=>vert?mapPos[x.other].y-mapPos[y.other].y:mapPos[x.other].x-mapPos[y.other].x);list.forEach((e,i)=>{const f=(i+1)/(list.length+1);anchor[e.k+'|'+id]=vert?{x:n.x+(sd==='r'?NW:0),y:Math.round(n.y+NH*f)}:{x:Math.round(n.x+NW*f),y:n.y+(sd==='b'?NH:0)}})}
for(const [k,r] of Object.entries(route)){const A=anchor[k+'|'+r.p],B=anchor[k+'|'+r.q];let pts,lx,ly;
if(r.o==='h'){const mx=Math.round((A.x+B.x)/2);pts=[A,{x:mx,y:A.y},{x:mx,y:B.y},B];lx=mx;ly=(A.y+B.y)/2}
else if(r.o==='v'){const my=Math.round((A.y+B.y)/2);pts=[A,{x:A.x,y:my},{x:B.x,y:my},B];lx=(A.x+B.x)/2;ly=my}
else{const x=Math.max(mapPos[r.p].x,mapPos[r.q].x)+NW+40;pts=[A,{x,y:A.y},{x,y:B.y},B];lx=x;ly=(A.y+B.y)/2;W=Math.max(W,x+160)}
const ln=c.querySelector(`[data-pair="${k}"]`),lb=c.querySelector(`[data-group="${k}"]`);if(ln)ln.setAttribute('d',roundPath(pts,10));if(lb){lb.style.left=lx+'px';lb.style.top=ly+'px'}}
c.style.width=W+'px';c.style.height=H+'px';const svg=$('#mapsvg');svg.setAttribute('width',W);svg.setAttribute('height',H)}
function bindMap(){const c=$('#mapcanvas'),tmp=$('#templine');let st=null;const pt=e=>{const b=c.getBoundingClientRect();return {x:e.clientX-b.left,y:e.clientY-b.top}};
c.onpointerdown=e=>{if(e.button!==0||e.target.closest('a,.linklabel'))return;if(e.target.closest('[data-node]'))mapBusy=true;const hd=e.target.closest('[data-handle]'),nd=e.target.closest('[data-node]');if(!nd)return;e.preventDefault();const id=Number(nd.dataset.node),p=pt(e);c.setPointerCapture(e.pointerId);
if(hd){const a=mapPos[id];st={mode:'link',id};tmp.setAttribute('x1',a.x+NW/2);tmp.setAttribute('y1',a.y+NH/2);tmp.setAttribute('x2',p.x);tmp.setAttribute('y2',p.y);tmp.setAttribute('visibility','visible')}else{st={mode:'move',id,nd,dx:p.x-mapPos[id].x,dy:p.y-mapPos[id].y,sx:p.x,sy:p.y,moved:false};nd.classList.add('dragging')}};
c.onpointermove=e=>{if(!st)return;const p=pt(e);if(st.mode==='link'){tmp.setAttribute('x2',p.x);tmp.setAttribute('y2',p.y);return}if(Math.abs(p.x-st.sx)+Math.abs(p.y-st.sy)>4)st.moved=true;if(!st.moved)return;mapPos[st.id]={x:Math.max(0,Math.round((p.x-st.dx)/10)*10),y:Math.max(0,Math.round((p.y-st.dy)/10)*10)};layoutMap()};
c.onpointerup=e=>{mapBusy=false;if(!st)return;const s=st;st=null;try{c.releasePointerCapture(e.pointerId)}catch{}if(s.mode==='link'){tmp.setAttribute('visibility','hidden');const t=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-node]');const to=t&&Number(t.dataset.node);if(to&&to!==s.id)edit('links',0,{from:String(s.id),to:String(to)});return}s.nd.classList.remove('dragging');const r=get(s.id);if(!s.moved){if(r)edit(r.kind,r.id);return}const p=mapPos[s.id];run(async()=>{const res=await api('position',{id:s.id,x:p.x,y:p.y});if(r){r.data.x=p.x;r.data.y=p.y;r.revision=res.revision}})};
c.onpointercancel=()=>{mapBusy=false;if(st?.nd)st.nd.classList.remove('dragging');st=null;tmp.setAttribute('visibility','hidden')}}
