function matchDevice(b,ip){const a=ipNum(ip);if(!a||!b)return null;return records.find(r=>r.kind==='devices'&&String(r.data.building)===String(b)&&(String(r.data.ip||'')+'\n'+String(r.data.internal_ips||'')).split(/[\s,;]+/).some(x=>{const y=ipNum(x.replace(/\/\d{1,3}$/,''));return y&&y.v===a.v&&y.n===a.n}))||null}
function bindIpMatch(){const f=$('#fields'),nm=f.querySelector('[name="name"]'),ipEl=f.querySelector('[name="ip"]'),bl=f.querySelector('[name="building"]');if(!nm||!ipEl||!bl||!nm.parentElement||typeof document.createElement!=='function')return;const hint=document.createElement('small');hint.className='matchhint';nm.parentElement.appendChild(hint);let auto=true,last='';const upd=()=>{const d=matchDevice(bl.value,ipEl.value);hint.textContent=d?'✓ Matches device “'+d.data.name+'”'+(auto?' – name taken over':' – type nothing to use its name'):(ipNum(ipEl.value)&&bl.value?'No device at this location has this IP.':'');hint.classList.toggle('nomatch',!d);const st=f.querySelector('[name="status"]'),ty=f.querySelector('[name="type"]');if(d&&st&&st.value==='')st.value='Assigned';if(d&&ty&&ty.value===''&&d.data.type)ty.value=d.data.type;if(d&&auto){nm.value=d.data.name;last=d.data.name}else if(!d&&auto&&last&&nm.value===last){nm.value='';last=''}};nm.addEventListener('input',()=>{auto=nm.value.trim()==='';upd()});ipEl.addEventListener('input',upd);bl.addEventListener('change',upd);upd()}

const TYPES=['Router','Switch','Firewall','Access Point','Modem','Gateway','Server','Virtual machine','NAS','PC','Laptop','Mac','Tablet','Smartphone','Printer','Scanner','IP camera','VoIP phone','Smart TV','Encoder','Decoder','IRD / Receiver','Playout server','Streaming server','KVM / IPMI','UPS','PDU','IoT device','DHCP pool','Reserved'];
function typeOptions(){const used=records.filter(r=>(r.kind==='ips'||r.kind==='devices')&&r.data.type).map(r=>String(r.data.type).trim()),seen=new Set(),out=[];for(const t of [...TYPES,...used.sort((a,b)=>a.localeCompare(b))]){const k=t.toLowerCase();if(t&&!seen.has(k)){seen.add(k);out.push(t)}}return out}

