 racks:['Racks','racks',r=>({ID:r.id,Name:r.data.name,Location:label(r.data.building),'Height (U)':r.data.height,'Used (U)':rackUsed(r.id),Notes:r.data.note})],
 rack_items:['Rack items','mounts',m=>({ID:m.id,Rack:label(m.data.rack),Location:label(get(m.data.rack)?.data.building),'Lowest U':m.data.position,'Height (U)':m.data.size,Width:m.data.width||'full',Name:m.data.name,Type:m.data.type,Device:m.data.device?label(m.data.device):'',IP:get(m.data.ip_id)?.data.ip||'',Notes:m.data.note})],
