async function exportCsv(key){const [,kind,map]=CSV[key];const src=kind==='software'?(await api('software',{})).files:records.filter(r=>r.kind===kind);const rows=src.map(map);const head=rows.length?Object.keys(rows[0]):Object.keys(map({id:'',data:{}}));const text='﻿'+[head,...rows.map(r=>head.map(h=>r[h]))].map(r=>r.map(csvCell).join(',')).join('\r\n')+'\r\n';saveBlob(`ciegolinkinfrahub-${key}-${stamp()}.csv`,new Blob([text],{type:'text/csv;charset=utf-8'}));toast(CSV[key][0]+' exported')}
function dataPanel(){const n=k=>k==='software'?'':records.filter(r=>r.kind===CSV[k][1]).length;
return `<div class="field-wide datagrid"><section class="datacard"><h3>Export · JSON</h3><p class="formnote">Everything in one file: locations, devices, IP addresses, credentials, map elements and positions, connections, software list and users. Every reference keeps ID and name – for backups or a move to a new system.</p>
<div id="export-box" class="databox"><label class="check"><input type="checkbox" id="ex-pw"> Include passwords (plain text)</label><label class="check"><input type="checkbox" id="ex-files"> Include credential files</label><label id="ex-confirm" hidden>Confirm with your current password<input type="password" id="ex-pass" maxlength="72"></label><p class="formnote danger" id="ex-warn" hidden>The file contains secrets without encryption. Store it encrypted and delete it after use.</p><button type="button" class="primary" id="export-json">Download JSON</button></div>
<h3>Export · CSV</h3><p class="formnote">One file per table for Excel. Never contains passwords.</p><div class="exportlist">${Object.entries(CSV).map(([k,[l]])=>`<button type="button" data-csv="${k}"><span>${E(l)}</span><small>${n(k)}</small></button>`).join('')}</div></section>
<section class="datacard"><h3>Import · JSON</h3><p class="formnote">Imports a JSON export of the Infrastructure Hub. Users and software files are not imported. Invalid data aborts the whole import – nothing is changed then.</p>
<div class="databox"><label>Export file<input type="file" id="im-file" accept=".json,application/json"></label><div id="im-preview" class="formnote"></div>
<label class="check"><input type="radio" name="im-mode" value="add" checked> Merge with existing data</label><p class="formnote">Existing entries (same name, same IP in the same location) are kept and not duplicated.</p><label class="check"><input type="radio" name="im-mode" value="replace"> Replace all existing data</label><p class="formnote danger" id="im-warn" hidden>All current locations, devices, IPs, credentials (incl. files), racks, elements, connections and documents will be deleted first.</p>
<label>Confirm with your current password<input type="password" id="im-pass" maxlength="72"></label><button type="button" class="primary" id="import-json" disabled>Import</button></div></section></div>
<p class="formnote field-wide">Software files are stored in <code>data/software/</code> on the server and are not part of the JSON. For a 1:1 server backup copy the <code>data/</code> folder together with <code>config/config.php</code>.</p>`}
function bindData(){const F=$('#fields');let parsed=null;
F.querySelectorAll('input[type=password]').forEach(i=>i.addEventListener('keydown',e=>{if(e.key==='Enter')e.preventDefault()}));
const exUpd=()=>{const secret=$('#ex-pw').checked||$('#ex-files').checked;$('#ex-confirm').hidden=!secret;$('#ex-warn').hidden=!$('#ex-pw').checked};$('#ex-pw').onchange=$('#ex-files').onchange=exUpd;
$('#export-json').onclick=()=>run(async()=>{const data={passwords:$('#ex-pw').checked,files:$('#ex-files').checked,password:$('#ex-pass').value};if((data.passwords||data.files)&&!data.password)throw Error('Enter your current password.');$('#ex-pass').value='';const b=$('#export-json');b.disabled=true;try{const d=await api('export',data);saveBlob(`ciegolinkinfrahub-export-${stamp()}.json`,new Blob([JSON.stringify(d,null,2)],{type:'application/json'}));toast('Export downloaded')}finally{b.disabled=false}});
F.querySelectorAll('[name=im-mode]').forEach(r=>r.onchange=()=>{$('#im-warn').hidden=F.querySelector('[name=im-mode]:checked').value!=='replace'});
$('#im-file').onchange=e=>run(async()=>{parsed=null;$('#import-json').disabled=true;$('#im-preview').textContent='';const f=e.target.files[0];if(!f)return;let d;try{d=JSON.parse(await f.text())}catch{throw Error('The file is not valid JSON.')}if(d?.format!=='ciegolink-infrahub-export')throw Error('This is not an Infrastructure Hub export file.');parsed=d;const c=k=>Array.isArray(d[k])?d[k].length:0;$('#im-preview').innerHTML=`<b>${E(f.name)}</b> · exported ${E(String(d.exported_at||'').slice(0,10))} by ${E(d.exported_by||'—')}<br>${c('locations')} locations · ${c('devices')} devices · ${c('ip_addresses')} IP records · ${c('credentials')} credentials · ${c('elements')} elements · ${c('connections')} connections<br>Passwords included: ${d.includes_passwords?'yes':'no – credentials are imported without password'}`;$('#import-json').disabled=false});
$('#import-json').onclick=()=>run(async()=>{if(!parsed)throw Error('Choose an export file first.');const replace=F.querySelector('[name=im-mode]:checked').value==='replace',password=$('#im-pass').value;if(!password)throw Error('Enter your current password.');if(replace&&!confirm('Delete ALL current infrastructure data and replace it with the file?'))return;const b=$('#import-json');b.disabled=true;try{const r=await api('import',{password,replace,data:parsed});$('#im-pass').value='';const c=r.counts;closeModal();await load();toast(`Imported: ${c.locations} locations, ${c.devices} devices, ${c.ip_addresses} IPs, ${c.credentials} credentials, ${c.connections} connections`+(c.existing?` · ${c.existing} already present`:''))}finally{b.disabled=false}})}

// Racks
const KINDS={buildings:'location',devices:'device',ips:'IP address',credentials:'credential',elements:'element',links:'connection',racks:'rack',mounts:'rack item',maintenance:'maintenance'};
function mountsOf(id){return records.filter(m=>m.kind==='mounts'&&m.data.rack===String(id))}
function rackUsed(id){return mountsOf(id).reduce((a,m)=>a+Number(m.data.size||1)*(['left','right'].includes(m.data.width)?.5:1),0)}
function uRange(m){const p=Number(m.data.position),t=p+Number(m.data.size||1)-1,w={left:' · left',right:' · right'}[m.data.width]||'';return (t>p?`U${p}–U${t}`:`U${p}`)+w}
function mountIp(m){const i=get(m.data.ip_id);if(i&&i.kind==='ips')return i.data.ip;const d=get(m.data.device);return d&&d.kind==='devices'?(ipSort(d.data.internal_ips).split('\n')[0]||ipSort(d.data.ip).split('\n')[0]||''):''}
function freeU(id){const r=get(id),h=Number(r?.data.height||42),used=new Set();for(const m of mountsOf(id))for(let u=Number(m.data.position);u<Number(m.data.position)+Number(m.data.size||1);u++)used.add(u);for(let u=1;u<=h;u++)if(!used.has(u))return u;return 1}
function deviceRack(id){const ms=records.filter(m=>m.kind==='mounts'&&m.data.device===String(id));if(!ms.length)return '';return `<div class="cardline"><span class="seclabel">RACK</span><span class="secinfo">${ms.map(m=>`${E(label(m.data.rack))} · ${E(uRange(m))}`).join(', ')}</span></div>`}
function renderRacks(){const can=user.role!=='reader',q=search.toLowerCase();
const mtext=m=>[m.data.name,m.data.type,m.data.note,get(m.data.device)?.data.name,mountIp(m),uRange(m)].join(' ').toLowerCase();
const racks=records.filter(r=>r.kind==='racks'&&(!filter||String(r.data.building)===filter)).sort((a,b)=>label(a.data.building).localeCompare(label(b.data.building))||String(a.data.name).localeCompare(String(b.data.name),undefined,{numeric:true}));
const shown=racks.filter(r=>!q||(r.data.name+' '+(r.data.note||'')).toLowerCase().includes(q)||mountsOf(r.id).some(m=>mtext(m).includes(q)));
const total=racks.reduce((a,r)=>a+Number(r.data.height||42),0),used=racks.reduce((a,r)=>a+rackUsed(r.id),0);
let h=`<div class="eyebrow">CIEGOLINK / RACKS</div><div class="heading"><div><h1>Rack <em>management.</em></h1><p>${can?'Click a free unit to mount a device there. Click an item to edit or move it.':'See what is mounted where.'}</p></div>${can?'<button class="primary" data-new="racks">＋ Add rack</button>':''}</div>
<div class="toolbar"><select id="loc" aria-label="Filter by location"><option value="">All locations</option>${records.filter(r=>r.kind==='buildings').map(r=>`<option value="${r.id}" ${filter===String(r.id)?'selected':''}>${E(r.data.name)}</option>`).join('')}</select><div class="toolright"><span class="autoping">${racks.length} ${racks.length===1?'rack':'racks'} · ${used} / ${total} U used</span>${searchBox('Rack, device, IP or type …')}</div></div>`;
h+=shown.length?`<div class="racks">${shown.map(r=>{const H=Number(r.data.height||42),ms=mountsOf(r.id),u=rackUsed(r.id),cells=[],occ={};
for(const m of ms){const w=['left','right'].includes(m.data.width)?m.data.width:'full';for(let x=Number(m.data.position);x<Number(m.data.position)+Number(m.data.size||1);x++){occ[x]=occ[x]||{};if(w==='full'){occ[x].left=occ[x].right=1}else occ[x][w]=1}}
const free=(x,side)=>can?`<button type="button" class="ru free" data-row="${H-x+1}" data-col="${side}" data-mount-at="${r.id}:${x}${side==='full'?'':':'+side}" title="Mount at U${x}${side==='full'?'':' · '+side+' half'}">＋</button>`:`<span class="ru free" data-row="${H-x+1}" data-col="${side}"></span>`;
for(let x=H;x>=1;x--){cells.push(`<span class="un" data-row="${H-x+1}">${x}</span>`);const o=occ[x]||{};if(!o.left&&!o.right)cells.push(free(x,'full'));else{if(!o.left)cells.push(free(x,'left'));if(!o.right)cells.push(free(x,'right'))}}
for(const m of ms){const p=Number(m.data.position),sz=Number(m.data.size||1),row=H-(p+sz-1)+1,w=['left','right'].includes(m.data.width)?m.data.width:'full',half=w!=='full',dv=get(m.data.device),ipr=get(m.data.ip_id),ip=mountIp(m),adm=ipr&&ipr.kind==='ips'?safeUrl(ipr.data.url):null,hit=!q||mtext(m).includes(q),ty=m.data.type||dv?.data.type||'';
const body=`<b>${E(m.data.name)}</b>${sz>1?`<small>${E([ty,uRange(m)].filter(Boolean).join(' · '))}</small>`:''}`;
const meta=`<span class="rmeta">${ip?`<button type="button" class="iplink" data-goto-ip="${E(ip)}" title="Show ${E(ip)} in IP management">${half?'IP':E(ip)}</button>`:sz===1&&ty&&!half?`<small>${E(ty)}</small>`:''}${adm?`<a class="admlink" href="${E(adm)}" target="_blank" rel="noopener noreferrer" title="Open web admin access">↗</a>`:''}${dv?nodeStatus(dv):''}</span>`;
cells.push(`<div class="ru item${hit?'':' dim'}${dv?' linked':''}${half?' half':''}" data-row="${row}" data-span="${sz}" data-col="${w}" title="${E(m.data.name+' · '+uRange(m))}">${can?`<button type="button" class="riedit" data-edit="${m.id}">${body}</button>`:`<span class="riedit">${body}</span>`}${meta}</div>`)}
return `<article class="rack"><div class="rackhead"><div><h3>${E(r.data.name)}</h3><small>${E(label(r.data.building))} · ${u}/${H} U used</small>${r.data.note?`<p class="racknote">${E(r.data.note)}</p>`:''}</div>${can?`<div class="actions"><button data-mount-at="${r.id}:${freeU(r.id)}">＋ Item</button><button data-edit="${r.id}">Edit</button></div>`:''}</div><div class="rackbar"><span data-w="${Math.min(100,Math.round(u/H*100))}"></span></div><div class="rackbody" data-rows="${H}">${cells.join('')}</div></article>`}).join('')}</div>`:`<div class="empty">${racks.length?'No rack matches your search.':'No racks yet. Add a rack for a location, then mount devices into it.'}</div>`;
$('#main').innerHTML=h+foot();rackStyles();$('#loc').onchange=e=>{filter=e.target.value;render()};bindSearch()}
// CSP: no inline styles, set grid positions via CSSOM
function rackStyles(){const m=$('#main');if(!m.querySelectorAll)return;m.querySelectorAll('.rackbody[data-rows]').forEach(e=>e.style.gridTemplateRows=`repeat(${e.dataset.rows},26px)`);m.querySelectorAll('.rackbody [data-row]').forEach(e=>{e.style.gridRow=e.dataset.span?`${e.dataset.row} / span ${e.dataset.span}`:e.dataset.row;if(e.dataset.col)e.style.gridColumn={full:'2 / 4',left:'2',right:'3'}[e.dataset.col]});m.querySelectorAll('.rackbar [data-w]').forEach(e=>e.style.width=e.dataset.w+'%')}
function bindMountForm(){const f=$('#fields'),dv=f.querySelector('[name=device]'),ip=f.querySelector('[name=ip_id]'),nm=f.querySelector('[name=name]'),ty=f.querySelector('[name=type]');if(!dv||!ip||!nm)return;const upd=()=>{const d=get(dv.value);nm.placeholder=d?d.data.name:'Required without linked device';if(!d)return;if(ty&&!ty.value&&d.data.type)ty.value=d.data.type;if(!ip.value){const addrs=(String(d.data.internal_ips||'')+'\n'+String(d.data.ip||'')).split(/\s+/).filter(Boolean);const hit=records.find(r=>r.kind==='ips'&&addrs.some(a=>{const x=ipNum(a),y=ipNum(r.data.ip);return x&&y&&x.v===y.v&&x.n===y.n}));if(hit)ip.value=String(hit.id)}};dv.addEventListener('change',upd);upd()}
document.addEventListener('click',e=>{const b=e.target.closest('button[data-mount-at]');if(!b)return;const [rack,u,side]=b.dataset.mountAt.split(':');edit('mounts',0,{rack,position:u,size:'1',width:side||'full'})});
document.addEventListener('click',e=>{const b=e.target.closest('button[data-goto-ip]');if(!b)return;page='ips';filter='';ipTab='';search=b.dataset.gotoIp;run(load)});

// SSH terminal
let termState=null;
function loadScript(src){return new Promise((ok,ko)=>{if(document.querySelector(`script[data-src="${src}"]`))return ok();const sc=document.createElement('script');sc.src=src+'?v='+encodeURIComponent(appVersion);sc.dataset.src=src;sc.onload=ok;sc.onerror=()=>ko(Error('Terminal component could not be loaded.'));document.head.appendChild(sc)})}
async function loadXterm(){if(window.Terminal)return;await loadScript('assets/vendor/xterm/xterm.js');await loadScript('assets/vendor/xterm/addon-fit.js');await loadScript('assets/vendor/xterm/addon-canvas.js')}
function sshDialog(id){const r=get(id);if(!r)return;const d=r.data,ips=[...ipSort(d.internal_ips).split('\n'),...ipSort(d.ip).split('\n')].filter(Boolean);
const creds=records.filter(c=>c.kind==='credentials'&&c.data.device===String(id)).sort((a,b)=>String(a.data.name).localeCompare(String(b.data.name)));
modal('Terminal · '+d.name,`<label>Address<select name="host" required>${ips.map(ip=>`<option value="${E(ip)}">${E(ip)}${ipSort(d.internal_ips).split('\n').includes(ip)?' · internal':' · external'}</option>`).join('')}</select></label><label>Port<input name="port" type="number" min="1" max="65535" value="22" required></label>
<label>Login<select name="credential_id" id="ssh-cred">${creds.map(c=>`<option value="${c.id}">${E(c.data.name)}${c.data.username?' · '+E(c.data.username):''}</option>`).join('')}<option value="">Enter manually …</option></select></label><label>Username<input name="username" id="ssh-user" maxlength="128" placeholder="From the credential"></label>
<label id="ssh-pass-l" hidden>Password<input name="password" type="password" id="ssh-pass" maxlength="1024"></label><label id="ssh-key-l">Private key (optional)<select name="key_id" id="ssh-key"><option value="">No key – use password</option></select><small>Key files come from the credential's Files. The credential password is used as key passphrase.</small></label>
<p class="formnote field-wide">The login is sent from the server; the browser only receives a one-time ticket. The host key is stored on first connect, a changed key blocks the connection. Every session is logged. <button type="button" class="linkbtn" id="ssh-forget">Forget stored host key</button></p>`,async data=>{const t=await api('ssh_ticket',{device_id:id,host:data.host,port:Number(data.port),credential_id:Number(data.credential_id||0),key_id:Number(data.key_id||0),username:data.username||'',password:data.password||'',cols:120,rows:32});return ()=>openTerminal(t,`${d.name} · ${data.host}`)});
$('#form').querySelector('.dialogactions button.primary').textContent='Connect';
const cred=$('#ssh-cred'),keySel=$('#ssh-key');const upd=()=>run(async()=>{const manual=!cred.value;$('#ssh-pass-l').hidden=!manual;$('#ssh-key-l').hidden=manual;$('#ssh-user').placeholder=manual?'Required':(get(cred.value)?.data.username||'Required');keySel.innerHTML='<option value="">No key – use password</option>';if(manual)return;const f=await api('attachments',{credential_id:Number(cred.value)});keySel.insertAdjacentHTML('beforeend',f.files.map(x=>`<option value="${x.id}">${E(x.filename)}</option>`).join(''));const guess=f.files.find(x=>/(^id_|\.pem$|\.key$|ppk$)/i.test(x.filename));if(guess)keySel.value=String(guess.id)});cred.onchange=upd;upd();
$('#ssh-forget').onclick=()=>run(async()=>{const h=$('#fields [name=host]').value,p=Number($('#fields [name=port]').value||22);if(!confirm(`Forget the stored host key of ${h}:${p}? Only do this if the server was reinstalled on purpose.`))return;const r=await api('ssh_forget',{host:h,port:p});toast(r.removed?'Host key forgotten. The next connect stores the new key.':'No stored host key for this address.')})}
async function openTerminal(t,title){await loadXterm();closeTerminal(true);const dlg=$('#term'),box=$('#termbox'),st=$('#termstate');$('#termtitle').textContent=title;st.textContent='Connecting …';st.className='status';box.innerHTML='';dlg.classList.remove('full');dlg.showModal();
const term=new Terminal({cursorBlink:true,fontFamily:'Mono, "JetBrains Mono", monospace',fontSize:14,scrollback:5000,theme:{background:'#111315',foreground:'#eaeae2',cursor:'#53bdb3',selectionBackground:'#19858066'}});const fit=new FitAddon.FitAddon();term.loadAddon(fit);term.open(box);try{term.loadAddon(new CanvasAddon.CanvasAddon())}catch{}fit.fit();term.focus();
const ws=new WebSocket((location.protocol==='https:'?'wss://':'ws://')+location.host+t.ws+'?ticket='+encodeURIComponent(t.ticket));ws.binaryType='arraybuffer';
const send=o=>{if(ws.readyState===1)ws.send(JSON.stringify(o))};
ws.onopen=()=>send({t:'r',c:term.cols,r:term.rows});
ws.onmessage=e=>{if(typeof e.data!=='string'){term.write(new Uint8Array(e.data));return}let m;try{m=JSON.parse(e.data)}catch{return}if(m.t==='info')term.writeln('\x1b[2m'+m.m+'\x1b[0m');else if(m.t==='err'){term.writeln('\r\n\x1b[31m'+m.m+'\x1b[0m');st.textContent='Error';st.className='status down'}else if(m.t==='ready'){st.textContent='Connected · '+m.m;st.className='status up';send({t:'r',c:term.cols,r:term.rows})}else if(m.t==='closed'){st.textContent='Closed';st.className='status'}};
ws.onclose=()=>{if(st.textContent.startsWith('Connected')||st.textContent.startsWith('Connecting')){st.textContent='Disconnected';st.className='status'}term.writeln('\r\n\x1b[2m[session ended]\x1b[0m')};
term.onData(d=>send({t:'d',d}));term.onResize(({cols,rows})=>send({t:'r',c:cols,r:rows}));
const onWin=()=>{try{fit.fit()}catch{}};window.addEventListener('resize',onWin);termState={term,ws,fit,onWin}}
function closeTerminal(silent){if(!termState)return;const {term,ws,onWin}=termState;termState=null;window.removeEventListener('resize',onWin);try{ws.close()}catch{}try{term.dispose()}catch{}if(!silent&&$('#term').open)$('#term').close()}
if(typeof document.getElementById==='function'&&document.getElementById('term')){$('#termclose').onclick=()=>closeTerminal();$('#termfull').onclick=()=>{$('#term').classList.toggle('full');setTimeout(()=>{try{termState?.fit.fit()}catch{}},50)};$('#term').addEventListener('cancel',e=>e.preventDefault())}
document.addEventListener('click',e=>{const b=e.target.closest('button[data-ssh]');if(b)sshDialog(Number(b.dataset.ssh))});

// Audit log
let auditState={page:1,q:''},auditReq=0;
async function loadAudit(){const box=$('#audit-box');if(!box)return;const n=++auditReq,d=await api('audit',auditState);if(n!==auditReq||!$('#audit-box'))return;auditState.page=d.page;const from=d.total?(d.page-1)*d.per+1:0,to=Math.min(d.page*d.per,d.total);
$('#audit-box').innerHTML=table(['Time (UTC)','User','Action','Target','IP'],d.entries.map(r=>`<td class="nowrap">${E(String(r.at).replace('T',' ').replace(/\+00:00$/,''))}</td><td>${E(r.actor)}</td><td><span class="pill">${E(r.action)}</span></td><td class="wrap">${E(r.target)}</td><td><code>${E(r.ip)}</code></td>`))+`<div class="pager"><span class="formnote">${d.total?`${from}–${to} of ${d.total}`:'No entries'}${auditState.q?` matching “${E(auditState.q)}”`:''}</span><div class="actions"><button type="button" data-audit-page="1" ${d.page<=1?'disabled':''}>« First</button><button type="button" data-audit-page="${d.page-1}" ${d.page<=1?'disabled':''}>‹ Back</button><span class="pageno">Page ${d.page} / ${d.pages}</span><button type="button" data-audit-page="${d.page+1}" ${d.page>=d.pages?'disabled':''}>Next ›</button><button type="button" data-audit-page="${d.pages}" ${d.page>=d.pages?'disabled':''}>Last »</button></div></div>`}
document.addEventListener('click',e=>{const b=e.target.closest('button[data-audit-page]');if(!b||b.disabled)return;auditState.page=Number(b.dataset.auditPage);run(loadAudit)});
// System info
function manualCard(){return `<div class="field-wide manualcard"><div><b>User manual</b><p class="formnote">All modules explained step by step, with screenshots.</p></div><a class="btnlink" href="manual/" target="_blank" rel="noopener">Open manual ↗</a></div>`}
function systemPanel(d){if(!d)return manualCard()+`<div class="field-wide sysgrid one"><section class="datacard"><h3>CiegoLink Infrastructure Hub</h3><p class="sysver">Version <b>${E(appVersion)}</b></p></section></div>`;const g=d.gateway||{};return manualCard()+`<div class="field-wide sysgrid"><section class="datacard"><h3>${E(d.app.name)}</h3><p class="sysver">Version <b>${E(d.app.version)}</b></p><p class="formnote">Changes per version are listed in CHANGELOG.md in the project folder.</p>
<h3>SSH terminal</h3><p class="formnote">${g.reachable?`Gateway ${E(g.gateway||'')} running · ${Number(g.sessions||0)} open session(s)`:g.configured?'<span class="danger">Configured, but the gateway service is not reachable.</span>':'Not installed (optional, needs its own server – see ssh-gateway/setup.sh).'}</p></section>
<section class="datacard"><h3>Server</h3><div class="kv">${Object.entries(d.server).map(([k,v])=>`<span>${E(k)}</span><b>${E(v)}</b>`).join('')}</div></section></div>
<div class="field-wide"><h3 class="sysh">Software components</h3>${table(['Component','Version','Used for','License'],d.components.map(c=>`<td><b>${E(c.name)}</b></td><td><code>${E(c.version)}</code></td><td>${E(c.use)}</td><td>${E(c.license)}</td>`))}</div>`}

// Documentation
let docList=[],docCur=null,docEdit=null,docQ='',docDirty=false,mdReady=null;
async function loadMd(){if(window.marked&&window.DOMPurify&&window.TurndownService)return;mdReady=mdReady||(async()=>{for(const f of ['marked.min.js','purify.min.js','turndown.js','turndown-plugin-gfm.js'])await loadScript('assets/vendor/markdown/'+f);
DOMPurify.addHook('afterSanitizeAttributes',n=>{if(n.tagName==='A'){n.setAttribute('target','_blank');n.setAttribute('rel','noopener noreferrer')}n.removeAttribute('style')})})();return mdReady}
function mdToHtml(md){return DOMPurify.sanitize(marked.parse(String(md||''),{gfm:true,breaks:false}),{FORBID_TAGS:['style','img','iframe','form','input'],FORBID_ATTR:['style']})}
let td=null;function htmlToMd(html){if(!td){td=new TurndownService({headingStyle:'atx',codeBlockStyle:'fenced',bulletListMarker:'-',emDelimiter:'*',strongDelimiter:'**',hr:'---'});td.use(turndownPluginGfm.gfm);td.addRule('b',{filter:['b'],replacement:c=>c.trim()?'**'+c+'**':''});td.addRule('i',{filter:['i'],replacement:c=>c.trim()?'*'+c+'*':''});td.addRule('emptyQuote',{filter:n=>n.nodeName==='BLOCKQUOTE'&&!n.textContent.replace(/[\s\u200b\u00a0]/g,''),replacement:()=>''})}const clean=DOMPurify.sanitize(String(html).replace(/\u200b/g,''),{FORBID_TAGS:['font','span','style'],FORBID_ATTR:['style','class','color','face','size']});return td.turndown(clean).replace(/[ \t]+$/gm,'').replace(/\n{3,}/g,'\n\n').trim()+'\n'}
function docTime(t){try{return new Date(t).toLocaleString([], {dateStyle:'medium',timeStyle:'short'})}catch{return t}}
function docListHtml(){if(!docList.length)return `<p class="formnote doclist-empty">${docQ?'No document matches your search.':'No documents yet.'}</p>`;const groups={};for(const d of docList)(groups[d.category||'General']=groups[d.category||'General']||[]).push(d);
return Object.entries(groups).map(([c,ds])=>`<div class="docgroup"><small>${E(c)}</small>${ds.map(d=>`<button type="button" class="docitem${docCur&&docCur.id===Number(d.id)?' active':''}" data-doc="${Number(d.id)}"><b>${E(d.title)}</b><span>${E(docTime(d.updated_at))}${d.updated_by?' · '+E(d.updated_by):''}</span></button>`).join('')}</div>`).join('')}
function renderDocs(){const can=user.role!=='reader';
$('#main').innerHTML=`<div class="eyebrow">CIEGOLINK / DOCUMENTATION</div><div class="heading"><div><h1>Team <em>documentation.</em></h1><p>Procedures, how-tos and notes for the team. Write visually or in Markdown${can?'':' (read only)'}.</p></div>${can?'<button class="primary" data-doc-new="1">＋ New document</button>':''}</div>
<div class="docs"><aside class="doclist"><input id="doc-q" placeholder="Search titles and text …" aria-label="Search documentation" value="${E(docQ)}" autocomplete="off"><div id="doclist-items">${docListHtml()}</div></aside><section class="docpane" id="docpane"></section></div>`+foot();
let tm;$('#doc-q').oninput=e=>{clearTimeout(tm);tm=setTimeout(()=>run(async()=>{docQ=e.target.value.trim();docList=(await api('docs',{q:docQ})).docs;$('#doclist-items').innerHTML=docListHtml()}),250)};
if(docEdit)return renderDocEditor();if(docCur)return renderDocView();if(docList.length&&!docQ)return run(()=>openDoc(Number(docList[0].id)));$('#docpane').innerHTML=`<div class="empty">${can?'Create the first document with “＋ New document”.':'No document selected.'}</div>`}
async function openDoc(id){const d=(await api('doc',{id})).doc;docCur={...d,id:Number(d.id),revision:Number(d.revision)};docEdit=null;docDirty=false;if(page!=='docs')return;$('#doclist-items').innerHTML=docListHtml();renderDocView()}
function renderDocView(){const d=docCur,can=user.role!=='reader';$('#docpane').innerHTML=`<div class="dochead"><div>${d.category?`<span class="pill">${E(d.category)}</span>`:''}<h2>${E(d.title)}</h2><p class="formnote">Updated ${E(docTime(d.updated_at))}${d.updated_by?' by '+E(d.updated_by):''}</p></div><div class="actions">${can?'<button type="button" data-doc-edit="1">Edit</button>':''}<button type="button" data-doc-md="1">Download .md</button>${can?'<button type="button" data-doc-del="1">Delete</button>':''}</div></div><article class="mdview">${mdToHtml(d.body)||'<p class="formnote">This document is empty.</p>'}</article>`}
function docTool(){const b=(c,l,t)=>`<button type="button" data-cmd="${c}" title="${E(t)}">${l}</button>`;return `<div class="doctools" role="toolbar">${b('bold','<b>B</b>','Bold (Ctrl+B)')}${b('italic','<i>I</i>','Italic (Ctrl+I)')}${b('strike','<s>S</s>','Strikethrough')}${b('code','&lt;/&gt;','Inline code')}<span class="sep"></span>${b('h1','H1','Heading 1')}${b('h2','H2','Heading 2')}${b('h3','H3','Heading 3')}${b('p','¶','Normal text')}<span class="sep"></span>${b('ul','• List','Bullet list')}${b('ol','1. List','Numbered list')}${b('quote','❝','Quote')}${b('pre','{ }','Code block')}<span class="sep"></span>${b('link','Link','Insert link')}${b('table','Table','Insert table')}${b('hr','―','Horizontal line')}<span class="docmode"><button type="button" data-docmode="visual" class="${docEdit.mode==='visual'?'active':''}">Visual</button><button type="button" data-docmode="md" class="${docEdit.mode==='md'?'active':''}">Markdown</button></span></div>`}
function renderDocEditor(){const e=docEdit,cats=[...new Set(docList.map(d=>d.category).filter(Boolean))];
$('#docpane').innerHTML=`<div class="docform"><input id="doc-title" placeholder="Title" maxlength="200" value="${E(e.title)}" aria-label="Title"><input id="doc-cat" placeholder="Category (optional)" maxlength="80" list="doc-cats" value="${E(e.category)}" aria-label="Category"><datalist id="doc-cats">${cats.map(c=>`<option value="${E(c)}"></option>`).join('')}</datalist></div>${docTool()}
<div class="mdedit mdview" id="doc-visual" contenteditable="true" spellcheck="true" ${e.mode==='visual'?'':'hidden'}></div><textarea id="doc-src" class="mdsrc" spellcheck="false" ${e.mode==='md'?'':'hidden'}></textarea>
<div class="docsave"><span class="formnote">${e.mode==='visual'?'Formatting is saved as Markdown.':'Markdown: **bold**, *italic*, # heading, - list, [link](https://…), | table |'} Ctrl+S saves.</span><div class="actions"><button type="button" data-doc-cancel="1">Cancel</button><button type="button" class="primary" data-doc-save="1">Save</button></div></div>`;
const v=$('#doc-visual'),src=$('#doc-src');if(e.mode==='visual'){v.innerHTML=mdToHtml(e.body);try{document.execCommand('defaultParagraphSeparator',false,'p');document.execCommand('styleWithCSS',false,false)}catch{}}else src.value=e.body;
const dirty=()=>{docDirty=true};v.addEventListener('input',dirty);src.addEventListener('input',dirty);$('#doc-title').addEventListener('input',dirty);$('#doc-cat').addEventListener('input',dirty);
v.addEventListener('paste',ev=>{ev.preventDefault();const html=ev.clipboardData.getData('text/html'),txt=ev.clipboardData.getData('text/plain');if(html)document.execCommand('insertHTML',false,mdToHtml(htmlToMd(html)));else document.execCommand('insertText',false,txt);dirty()});
v.addEventListener('drop',ev=>ev.preventDefault());
const fo=e.mode==='visual'?v:src;if(fo.focus)fo.focus()}
function docCurrentBody(){return docEdit.mode==='visual'?htmlToMd($('#doc-visual').innerHTML):$('#doc-src').value}
function docSwitch(mode){if(!docEdit||docEdit.mode===mode)return;docEdit.body=docCurrentBody();docEdit.title=$('#doc-title').value;docEdit.category=$('#doc-cat').value;docEdit.mode=mode;try{localStorage.setItem('docmode',mode)}catch{}renderDocEditor()}
function mdWrap(t,a,b,ph){const s=t.selectionStart,e=t.selectionEnd,sel=t.value.slice(s,e)||ph;t.setRangeText(a+sel+b,s,e,'end');if(!t.value.slice(s,e))t.setSelectionRange(s+a.length,s+a.length+sel.length);t.focus();docDirty=true}
function mdLines(t,f){const v=t.value;let s=v.lastIndexOf('\n',t.selectionStart-1)+1,e=v.indexOf('\n',t.selectionEnd);if(e<0)e=v.length;const block=v.slice(s,e).split('\n').map(f).join('\n');t.setRangeText(block,s,e,'select');t.focus();docDirty=true}
const TABLE_MD='\n| Column 1 | Column 2 | Column 3 |\n| --- | --- | --- |\n|  |  |  |\n|  |  |  |\n';
function docCmd(c){if(docEdit.mode==='md'){const t=$('#doc-src');const map={bold:()=>mdWrap(t,'**','**','bold text'),italic:()=>mdWrap(t,'*','*','italic text'),strike:()=>mdWrap(t,'~~','~~','text'),code:()=>mdWrap(t,'`','`','code'),h1:()=>mdLines(t,l=>'# '+l.replace(/^#+\s*/,'')),h2:()=>mdLines(t,l=>'## '+l.replace(/^#+\s*/,'')),h3:()=>mdLines(t,l=>'### '+l.replace(/^#+\s*/,'')),p:()=>mdLines(t,l=>l.replace(/^(#+|>|-|\d+\.)\s*/,'')),ul:()=>mdLines(t,l=>'- '+l),ol:()=>mdLines(t,(l,i)=>`${i+1}. `+l),quote:()=>mdLines(t,l=>'> '+l),pre:()=>mdWrap(t,'\n```\n','\n```\n','code'),link:()=>{const u=prompt('Link address (https://…)','https://');if(u)mdWrap(t,'[','](' +u+')','link text')},table:()=>mdWrap(t,TABLE_MD,'',''),hr:()=>mdWrap(t,'\n\n---\n\n','','')};map[c]?.();return}
const v=$('#doc-visual');v.focus();const ex=(a,b)=>document.execCommand(a,false,b);
const map={bold:()=>ex('bold'),italic:()=>ex('italic'),strike:()=>ex('strikeThrough'),code:()=>{const sel=getSelection();if(!sel.rangeCount)return;const r=sel.getRangeAt(0);if(!v.contains(r.commonAncestorContainer))return;const inCode=(r.startContainer.nodeType===3?r.startContainer.parentElement:r.startContainer).closest('code');if(inCode&&v.contains(inCode)){inCode.replaceWith(document.createTextNode(inCode.textContent));return}const empty=r.collapsed,c=document.createElement('code');c.textContent=empty?'code':r.toString();r.deleteContents();const after=document.createTextNode('\u200b');r.insertNode(after);r.insertNode(c);const nr=document.createRange();if(empty)nr.selectNodeContents(c);else{nr.setStart(after,1);nr.collapse(true)}sel.removeAllRanges();sel.addRange(nr)},h1:()=>ex('formatBlock','H1'),h2:()=>ex('formatBlock','H2'),h3:()=>ex('formatBlock','H3'),p:()=>ex('formatBlock','P'),ul:()=>ex('insertUnorderedList'),ol:()=>ex('insertOrderedList'),quote:()=>ex('formatBlock','BLOCKQUOTE'),pre:()=>ex('formatBlock','PRE'),
link:()=>{const u=prompt('Link address (https://…)','https://');if(u&&/^(https?:|mailto:)/i.test(u.trim())){if(String(getSelection()))ex('createLink',u.trim());else ex('insertHTML',`<a href="${E(u.trim())}">${E(u.trim())}</a>`)}},table:()=>ex('insertHTML',mdToHtml(TABLE_MD)+'<p><br></p>'),hr:()=>ex('insertHorizontalRule')};map[c]?.();docDirty=true}
async function docSave(){const body=docCurrentBody(),title=$('#doc-title').value.trim(),category=$('#doc-cat').value.trim();if(!title)throw Error('Please enter a title.');const r=await api('doc_save',{id:docEdit.id||0,revision:docEdit.revision||0,title,category,body});docDirty=false;docEdit=null;docList=(await api('docs',{q:docQ})).docs;await openDoc(r.id);$('#doclist-items').innerHTML=docListHtml();toast('Saved')}
function docLeave(){return !docDirty||confirm('Discard unsaved changes to this document?')}
function startDocEdit(d){let mode='visual';try{mode=localStorage.getItem('docmode')||'visual'}catch{}docEdit={id:d?.id||0,revision:d?.revision||0,title:d?.title||'',category:d?.category||'',body:d?.body||'',mode:mode==='md'?'md':'visual'};docDirty=false;renderDocEditor()}
document.addEventListener('click',e=>{const t=e.target.closest('[data-page],[data-doc],[data-doc-new]');if(t&&docDirty&&docEdit&&!docLeave()){e.preventDefault();e.stopImmediatePropagation();return}if(t&&docDirty){docDirty=false;docEdit=null}if(t&&t.dataset.page&&t.dataset.page!=='docs'){docEdit=null;docCur=null}},true);
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;
if(b.dataset.doc)run(()=>openDoc(Number(b.dataset.doc)));
if(b.dataset.docNew){docCur=null;$('#doclist-items').innerHTML=docListHtml();startDocEdit(null)}
if(b.dataset.docEdit)startDocEdit(docCur);
if(b.dataset.docCancel){if(!docLeave())return;docDirty=false;docEdit=null;docCur?renderDocView():renderDocs()}
if(b.dataset.docSave)run(docSave);
if(b.dataset.docmode)docSwitch(b.dataset.docmode);
if(b.dataset.cmd){e.preventDefault();docCmd(b.dataset.cmd)}
if(b.dataset.docMd)saveBlob((docCur.title.replace(/[^\w.-]+/g,'-').replace(/^-+|-+$/g,'')||'document')+'.md',new Blob([docCur.body],{type:'text/markdown;charset=utf-8'}));
if(b.dataset.docDel)run(async()=>{if(!confirm('Permanently delete “'+docCur.title+'”?'))return;await api('doc_delete',{id:docCur.id,revision:docCur.revision});docCur=null;docList=(await api('docs',{q:docQ})).docs;toast('Deleted');renderDocs()})});
document.addEventListener('mousedown',e=>{if(e.target.closest('.doctools button[data-cmd]'))e.preventDefault()});
document.addEventListener('keydown',e=>{if(docEdit&&(e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='s'){e.preventDefault();run(docSave)}});
if(typeof window!=='undefined')window.addEventListener('beforeunload',e=>{if(docDirty){e.preventDefault();e.returnValue=''}});

// Maintenance
let mTab='current';
function mInfo(r){const st=Date.parse(r.data.start)||0,min=Number(r.data.duration)||0,en=st+min*60000,now=Date.now();return {st,en,min,status:r.data.state==='cancelled'?'cancelled':now<st?'upcoming':now<en?'active':'completed'}}
function mDate(t){return new Date(t).toLocaleString('en-GB',{weekday:'short',day:'2-digit',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'})}
function mDur(min){const d=Math.floor(min/1440),h=Math.floor(min%1440/60),m=min%60;return [d?d+' d':'',h?h+' h':'',m?m+' min':''].filter(Boolean).join(' ')||'0 min'}
function mLocal(t){const d=new Date(t),p=n=>String(n).padStart(2,'0');return `${d.getFullYear()}-${p(d.getMonth()+1)}-${p(d.getDate())}T${p(d.getHours())}:${p(d.getMinutes())}`}
function mDevs(v){return String(v||'').split('\n').filter(Boolean).map(id=>get(id)).filter(r=>r&&r.kind==='devices')}
function mDevPicker(v){const sel=new Set(String(v||'').split('\n').filter(Boolean)),devs=records.filter(r=>r.kind==='devices').sort((a,b)=>String(label(a.data.building)).localeCompare(String(label(b.data.building)))||String(a.data.name).localeCompare(String(b.data.name),undefined,{numeric:true}));if(!devs.length)return '<div class="field-wide formnote">No servers or devices yet.</div>';let last=null;return `<div class="field-wide"><label for="m-devq" class="mdevhead">Affected servers &amp; devices <small id="m-devn"></small></label><input id="m-devq" placeholder="Filter devices …" maxlength="80" autocomplete="off"><div class="mdevs" id="m-devs">${devs.map(r=>{const b=label(r.data.building)||'No location',head=b!==last?`<div class="mdevloc">${E(b)}</div>`:'';last=b;return head+`<label class="mdev" data-q="${E((r.data.name+' '+(r.data.type||'')+' '+b+' '+(r.data.ip||'')+' '+(r.data.internal_ips||'')).toLowerCase())}"><input type="checkbox" value="${r.id}" ${sel.has(String(r.id))?'checked':''}><span>${E(r.data.name)}</span>${r.data.type?`<small>${E(r.data.type)}</small>`:''}</label>`}).join('')}</div></div>`}
const M_LABEL={active:'In progress',upcoming:'Planned',completed:'Completed',cancelled:'Cancelled'};
function renderMaintenance(){const can=user.role!=='reader',q=search.toLowerCase(),all=records.filter(r=>r.kind==='maintenance').map(r=>({r,...mInfo(r)})).filter(x=>(Object.values(x.r.data).join(' ')+' '+mDevs(x.r.data.devices).map(r=>r.data.name).join(' ')).toLowerCase().includes(q)),
tabs=[['current','Active & planned',x=>x.status==='active'||x.status==='upcoming'],['completed','Completed',x=>x.status==='completed'],['cancelled','Cancelled',x=>x.status==='cancelled'],['all','All',()=>true]],cur=tabs.find(t=>t[0]===mTab)||tabs[0],
rows=all.filter(cur[2]).sort((a,b)=>mTab==='current'?a.st-b.st:b.st-a.st),active=all.filter(x=>x.status==='active');
let h=`<div class="eyebrow">CIEGOLINK / OPERATIONS</div><div class="heading"><div><h1>Maintenance <em>windows.</em></h1><p>Plan maintenance with date, time and duration. Public entries are available to other servers through the read-only maintenance API.</p></div><div class="headactions">${user.role==='admin'?'<button data-m-api="1">API access</button>':''}${can?'<button class="primary" data-new="maintenance">＋ Plan maintenance</button>':''}</div></div>`;
if(active.length)h+=`<div class="mbanner"><span class="dot partial"></span><b>Maintenance in progress:</b> ${active.map(x=>E(x.r.data.name)+' · until '+E(mDate(x.en))).join(' &nbsp;·&nbsp; ')}</div>`;
h+=`<div id="tabs" class="iptabs" role="tablist" aria-label="Maintenance">${tabs.map(([key,l,f])=>`<button type="button" role="tab" data-mtab="${key}" class="${mTab===key?'active':''}" aria-selected="${mTab===key}">${E(l)}<span class="tabcount">${all.filter(f).length}</span></button>`).join('')}</div><div class="toolbar"><span class="autoping">Times in your browser time zone</span><div class="toolright">${searchBox('Title, device, service or message …')}</div></div>`;
h+=table(['Status','Maintenance','Start','End','Duration','API',''],rows.map(x=>{const d=x.r.data,sv=String(d.services||'').split('\n').filter(Boolean);const dv=mDevs(d.devices);return `<td><span class="mstatus ${x.status}">${M_LABEL[x.status]}</span></td><td><b>${E(d.name)}</b>${dv.length?`<div class="mdevlist">${dv.map(r=>`<span>▣ ${E(r.data.name)}</span>`).join('')}</div>`:''}${sv.length?`<div class="msvc">${sv.map(s=>`<span class="pill">${E(s)}</span>`).join('')}</div>`:''}${d.message?`<div class="swnote">${E(d.message)}</div>`:''}${d.note?`<small class="swmeta">Internal: ${E(d.note)}</small>`:''}</td><td class="nowrap">${E(mDate(x.st))}</td><td class="nowrap">${E(mDate(x.en))}</td><td class="nowrap">${E(mDur(x.min))}</td><td>${d.public==='0'?'<span class="formnote">Internal</span>':'<span class="pill">Public</span>'}</td><td>${editButtons(x.r)}</td>`}));
$('#main').innerHTML=h+foot();bindSearch()}
function maintEdit(id){const r=id?get(id):null,d=r?.data||{},start=d.start?mLocal(d.start):mLocal(Math.ceil((Date.now()+3600000)/900000)*900000),min=Number(d.duration||60);
const fields=`<label class="field-wide">Title<input name="name" value="${E(d.name)}" required maxlength="200" placeholder="e.g. Playout server update"></label>
${mDevPicker(d.devices)}
<label>Start (date &amp; time)<input name="start" id="m-start" type="datetime-local" value="${E(start)}" required></label>
<label>Duration<span class="mdur"><input name="dur_h" id="m-h" type="number" min="0" max="720" step="1" value="${Math.floor(min/60)}" aria-label="Hours"><span>h</span><input name="dur_m" id="m-m" type="number" min="0" max="59" step="1" value="${min%60}" aria-label="Minutes"><span>min</span></span><small id="m-end"></small></label>
<label>Status<select name="state"><option value="planned">Planned</option><option value="cancelled" ${d.state==='cancelled'?'selected':''}>Cancelled</option></select></label>
<label>Visibility<select name="public"><option value="1">Public (shown in the API)</option><option value="0" ${d.public==='0'?'selected':''}>Internal only</option></select></label>
<label class="field-wide">Affected services (one per line)<textarea name="services" rows="3" maxlength="4096" placeholder="Playout\nSRT gateway\nEPG">${E(d.services)}</textarea></label>
<label class="field-wide">Public message<textarea name="message" rows="2" maxlength="4096" placeholder="Shown through the API, e.g. Short interruptions possible.">${E(d.message)}</textarea></label>
<label class="field-wide">Internal note<textarea name="note" rows="2" maxlength="4096" placeholder="Not shown in the API">${E(d.note)}</textarea></label>`;
modal(r?'Edit maintenance':'Plan maintenance',fields,async x=>{const s=new Date(x.start);if(isNaN(s))throw Error('Enter a valid start date and time.');const dur=Number(x.dur_h||0)*60+Number(x.dur_m||0);if(dur<1)throw Error('Enter a duration.');await api('save',{kind:'maintenance',id:r?.id||0,revision:r?.revision||0,data:{name:x.name,devices:[...document.querySelectorAll('#m-devs input:checked')].map(i=>i.value).join('\n'),start:s.toISOString(),duration:String(dur),state:x.state,public:x.public,services:x.services||'',message:x.message||'',note:x.note||''}});toast('Saved')});
const devn=()=>{const n=document.querySelectorAll('#m-devs input:checked').length;if($('#m-devn'))$('#m-devn').textContent=n?'· '+n+' selected':''};if($('#m-devs')){$('#m-devs').addEventListener('change',devn);devn();$('#m-devq').addEventListener('input',e=>{const q=e.target.value.toLowerCase();document.querySelectorAll('#m-devs .mdev').forEach(l=>l.hidden=!!q&&!l.dataset.q.includes(q))})}const upd=()=>{const s=new Date($('#m-start').value),dur=Number($('#m-h').value||0)*60+Number($('#m-m').value||0);$('#m-end').textContent=isNaN(s)||dur<1?'':'Ends '+mDate(s.getTime()+dur*60000)};['#m-start','#m-h','#m-m'].forEach(s=>$(s).addEventListener('input',upd));upd()}
function mEndpoint(){return location.origin+location.pathname.replace(/[^/]*$/,'')+'maintenance.php'}
async function mApi(){const d=await api('api_tokens',{}),url=mEndpoint();
modal('Maintenance API',`<div class="field-wide"><p class="formnote">Read-only access to <b>public</b> maintenance entries for other servers and websites. Each server gets its own token; revoke it here at any time. Tokens are only shown once.</p>
<p class="formnote">Endpoint <code>${E(url)}</code> <button type="button" data-copy-text="${E(url)}">Copy</button></p>
<pre class="mcode">curl -H "Authorization: Bearer &lt;token&gt;" "${E(url)}"
${E(url)}?scope=current|active|upcoming|completed|all&amp;days=90&amp;past=30</pre></div>
<div class="field-wide">${table(['Name','Token','Created','Last used',''],d.tokens.map(t=>`<td><b>${E(t.name)}</b></td><td><code>${E(t.prefix)}…</code></td><td class="nowrap">${E(new Date(t.created_at).toLocaleDateString())}<small class="swmeta"> ${E(t.created_by)}</small></td><td class="nowrap">${t.last_used?E(new Date(t.last_used).toLocaleString()):'Never'}</td><td><button type="button" class="dangerbtn" data-token-revoke="${t.id}" data-token-name="${E(t.name)}">Revoke</button></td>`))}</div>
<label class="field-wide">New token for<input name="name" maxlength="80" required placeholder="e.g. Website aw1.tv or Status page"></label>`,async x=>{const t=await api('api_token_create',{name:x.name});return ()=>mToken(t.token,url)});
$('#modal').classList.add('wide');$('#form').querySelector('.dialogactions button.primary').textContent='Create token'}
function mToken(tok,url){modal('Token created',`<div class="field-wide"><p class="notice">Copy the token now. It is stored only as a hash and cannot be shown again.</p><code class="secret">${E(tok)}</code><p><button type="button" class="primary" data-copy-text="${E(tok)}">Copy token</button></p><p class="formnote">Example</p><pre class="mcode">curl -H "Authorization: Bearer ${E(tok)}" "${E(url)}"</pre></div>`,async()=>()=>mApi());$('#modal').classList.add('wide');$('#form').querySelector('.dialogactions button.primary').textContent='Done'}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;
if(b.dataset.mtab){mTab=b.dataset.mtab;render()}
if(b.dataset.mApi)run(mApi);
if(b.dataset.copyText)navigator.clipboard.writeText(b.dataset.copyText).then(()=>toast('Copied'),()=>toast('Copy failed'));
if(b.dataset.tokenRevoke&&confirm('Revoke token “'+b.dataset.tokenName+'”? Servers using it lose access immediately.'))run(async()=>{await api('api_token_delete',{id:Number(b.dataset.tokenRevoke)});closeModal();await mApi();toast('Token revoked')})});
